using Azure;
using Azure.AI.OpenAI;

var client = new OpenAIClient(
    new Uri("https://my-openai.openai.azure.com/"),
    new AzureKeyCredential("my-api-key")
);

EmbeddingsOptions options = new EmbeddingsOptions()
{
    DeploymentName = "text-embedding-3-large",
    Input = { "Azure App Service is a fully managed platform for hosting web apps." }
};

Response<Embeddings> response = await client.GetEmbeddingsAsync(options);
ReadOnlyMemory<float> embedding = response.Value.Data[0].Embedding;

Console.WriteLine("Embedding dimensions: " + embedding.Length);
Console.WriteLine("First 5 values: " + string.Join(", ", embedding.Span.Slice(0, 5).ToArray()));
